//! Generates the TypeScript client and schema-specific native codec.

use std::fmt::Write;

use anyx_protocol::Schema;
use anyx_protocol::schema::{Field, Method, Shaped, Type, TypeKind};

use crate::names::camel_case;
use crate::{
    Error, method_words, pascal_case, type_parameter_name, typescript_error_name,
    typescript_type_taken,
};

pub fn typescript(schema: &Schema) -> Result<String, Error> {
    crate::check_names(schema)?;
    let mut out = String::new();
    writeln!(
        out,
        "// Generated by anyx-protocol-generate from the `{}` schema. To change it, change the schema and generate it again.\n",
        schema.name
    )
    .unwrap();
    for definition in &schema.types {
        out.push_str(&doc(&definition.doc, ""));
        let name = pascal_case(&definition.name);
        let generic = generic_name(schema, &name, &definition.parameters);
        match &definition.kind {
            TypeKind::Record(fields) => record(&mut out, schema, &generic, fields),
            TypeKind::Choice(variants) => union(&mut out, schema, &generic, variants),
            TypeKind::Distinct(underlying) => branded(
                &mut out,
                schema,
                &name,
                &definition.name.clone(),
                underlying,
            ),
        }
    }
    for method in &schema.methods {
        if !method.errors.is_empty() {
            writeln!(out, "/** The errors of `{}`. */", schema.call_name(method)).unwrap();
            let errors: Vec<Shaped> = schema.errors_of(method).into_iter().cloned().collect();
            union(
                &mut out,
                schema,
                &typescript_error_name(schema, method),
                &errors,
            );
        }
    }
    out.push_str(include_str!("typescript_native.ts"));
    out.push_str(&native_schema(schema));
    out.push_str(PRELUDE);
    let root_methods: Vec<String> = schema
        .methods
        .iter()
        .map(|method| {
            let signature = signature(schema, method);
            format!(
                "{}  {}({}): {} {{\n    return this.call({:?}, [{}]);\n  }}\n",
                doc(&method_doc(method), "  "),
                camel_case(&method_words(schema, method)),
                signature.parameters,
                signature.returned,
                schema.call_name(method),
                signature.arguments,
            )
        })
        .collect();
    let introspection = "  /** `SCHEMA`, returning the guide to the schema. */\n  schema(): Promise<Outcome<string, never>> {\n    return this.call(\"SCHEMA\", []);\n  }\n\n  /** `SCHEMA FILES`, returning the files of the schema, the entry first. */\n  schemaFiles(): Promise<Outcome<SchemaFile[], never>> {\n    return this.call(\"SCHEMA FILES\", []);\n  }\n".to_string();
    out.push_str(
        &root_methods
            .into_iter()
            .chain([introspection])
            .collect::<Vec<_>>()
            .join("\n"),
    );
    out.push_str("}\n");
    effects(&mut out, schema);
    Ok(out)
}

struct Signature {
    parameters: String,
    arguments: String,
    returned: String,
}

fn signature(schema: &Schema, method: &Method) -> Signature {
    let parameters = &method.shape.parameters;
    let errors = match method.errors.is_empty() {
        true => "never".to_string(),
        false => typescript_error_name(schema, method),
    };
    Signature {
        parameters: parameters
            .iter()
            .map(|parameter| {
                format!(
                    "{}: {}",
                    camel_case(&parameter.name),
                    ts_type(schema, &parameter.r#type)
                )
            })
            .collect::<Vec<_>>()
            .join(", "),
        arguments: parameters
            .iter()
            .map(|parameter| camel_case(&parameter.name))
            .collect::<Vec<_>>()
            .join(", "),
        returned: format!(
            "Promise<Outcome<{}, {errors}>>",
            method.returns.as_ref().map_or_else(
                || "void".to_string(),
                |returns| ts_type(schema, &returns.r#type)
            )
        ),
    }
}

const PRELUDE: &str = r#"/** What came of one call. */
export type Outcome<T, E> =
  | { kind: "value"; value: T }
  | { kind: "error"; error: E }
  /** An earlier call failed with an internal error, so this one didn't run. */
  | { kind: "notRun" }
  /** The server failed. It logged why. */
  | { kind: "internalError" }
  /** The server couldn't read the request. */
  | { kind: "invalidRequest"; line: number; column: number; message: string };

/** A protocol-level failure returned by the server. Declared method errors
 * remain available on `outcome` as the `error` variant. */
export class OutcomeFailure<E> extends Error {
  constructor(readonly outcome: Exclude<Outcome<never, E>, { kind: "value" }>) {
    super(`AnyX outcome: ${outcome.kind}`);
    this.name = "OutcomeFailure";
  }
}

/** Return a successful value or throw an OutcomeFailure containing the
 * declared error or protocol failure. Transport and codec failures reject
 * the client promise directly and are not represented as outcomes. */
export function unwrapOutcome<T, E>(outcome: Outcome<T, E>): T {
  if (outcome.kind === "value") return outcome.value;
  throw new OutcomeFailure(outcome);
}

interface QueuedCall {
  method: string;
  args: unknown[];
  resolve: (outcome: Outcome<never, never>) => void;
  reject: (reason: unknown) => void;
}

/** Calls the schema's methods using a transport that sends AnyX text. Codec
 * and transport failures reject the call (and every call in its batch). */
export class Client {
  private queue: QueuedCall[] | null = null;
  constructor(private readonly send: (request: string) => Promise<string>) {}
  async batch<R>(build: (calls: Client) => Promise<R>[]): Promise<R[]> {
    const calls = new Client(this.send);
    const queue: QueuedCall[] = [];
    calls.queue = queue;
    const outcomes = build(calls);
    calls.queue = null;
    if (queue.length) void this.sendCalls(queue);
    return Promise.all(outcomes);
  }
  private call<T, E>(method: string, args: unknown[]): Promise<Outcome<T, E>> {
    return new Promise((resolve, reject) => {
      const call: QueuedCall = { method, args, resolve: resolve as (outcome: Outcome<never, never>) => void, reject };
      if (this.queue) this.queue.push(call); else void this.sendCalls([call]);
    });
  }
  private async sendCalls(calls: QueuedCall[]): Promise<void> {
    try {
      const descriptors = calls.map(c => methods[c.method] || fail(`unknown method ${c.method}`));
      const request = calls.map((c, i) => encodeCall(descriptors[i], c.args)).join(",\n") + "\n";
      const response = await this.send(request);
      const outcomes = decodeResponses(descriptors, response);
      calls.forEach((call, i) => call.resolve(outcomes[i]));
    } catch (error) { calls.forEach(call => call.reject(error)); }
  }


"#;

fn ts_type(schema: &Schema, r#type: &Type) -> String {
    match r#type {
        Type::Text => "string".to_string(),
        // Bytes are carried as base64 on the wire.
        Type::Bytes => "Uint8Array".to_string(),
        Type::Integer => "bigint".to_string(),
        Type::Float => "number".to_string(),
        Type::Instant => "Date".to_string(),
        // Whole milliseconds, preserving the protocol's unsigned 64-bit range.
        Type::Duration => "bigint".to_string(),
        Type::Refined(base, _) => ts_type(schema, base),
        Type::List(item) => format!("{}[]", ts_type(schema, item)),
        Type::Map(value) => format!("Record<string, {}>", ts_type(schema, value)),
        Type::Named(index) => {
            let definition = &schema.types[*index];
            pascal_case(&definition.name)
        }
        Type::Generic(index, arguments) => {
            let definition = &schema.types[*index];
            let arguments: Vec<String> = arguments
                .iter()
                .map(|argument| ts_type(schema, argument))
                .collect();
            format!(
                "{}<{}>",
                pascal_case(&definition.name),
                arguments.join(", ")
            )
        }
        Type::Parameter(name) => parameter_name(schema, name),
    }
}

/// A type parameter as TypeScript names it: `item` is `Item`.
fn parameter_name(schema: &Schema, name: &str) -> String {
    type_parameter_name(name, |taken| typescript_type_taken(schema, taken))
}

/// `name` with the type parameters `parameters`: `PageOf<Item>`.
fn generic_name(schema: &Schema, name: &str, parameters: &[String]) -> String {
    match parameters.is_empty() {
        true => name.to_string(),
        false => format!(
            "{name}<{}>",
            parameters
                .iter()
                .map(|parameter| parameter_name(schema, parameter))
                .collect::<Vec<_>>()
                .join(", ")
        ),
    }
}

/// A method's doc, what its markers claim, then its examples.
fn method_doc(method: &Method) -> Option<String> {
    let parts: Vec<String> = method
        .doc
        .clone()
        .into_iter()
        .chain([crate::effects_doc(method)])
        .chain(crate::examples_doc(method))
        .collect();
    Some(parts.join("\n\n"))
}

/// `EFFECTS`, each method's markers by its full name, or an overload's by
/// its name with its parameters' types, as the client calls it, for a tool to decide whether to retry a call or ask before sending
/// it.
fn effects(out: &mut String, schema: &Schema) {
    out.push_str(EFFECTS);
    for method in schema.methods.iter().chain(&schema.built_ins) {
        let undone_by = match &method.undone_by {
            Some(undo) => format!("{:?}", undo.text),
            None => "null".to_string(),
        };
        writeln!(
            out,
            "  {:?}: {{ readOnly: {}, idempotent: {}, undoneBy: {undone_by} }},",
            schema.call_name(method),
            method.effect.read_only(),
            method.effect.idempotent(),
        )
        .unwrap();
    }
    out.push_str("};\n");
}

const EFFECTS: &str = r#"
/** What a call of a method may do, as the schema's markers claim. A method
 * without markers is the worst case: all `false` and `null`. */
export interface Effects {
  /** `READ ONLY`: the call changes nothing, so it may be sent freely. */
  readonly readOnly: boolean;
  /** `IDEMPOTENT`, or `READ ONLY`, which implies it: calling it again with
   * the same arguments changes nothing more, so it may be retried after a
   * lost response. The retry may still answer differently, such as with an
   * error saying it is already done. */
  readonly idempotent: boolean;
  /** `UNDONE BY`: the call that undoes it, as written in the schema, in the
   * protocol's namespace, with the method's own arguments in its slots. */
  readonly undoneBy: string | null;
}

/** Each method's `Effects`, by the full name the client calls it by. Only a
 * method whose `idempotent` is true may be retried on its own. */
export const EFFECTS: { readonly [method: string]: Effects } = {
"#;

fn doc(doc: &Option<String>, indent: &str) -> String {
    let Some(doc) = doc else { return String::new() };
    let doc = doc.replace("*/", "*\\/");
    let lines: Vec<&str> = doc.lines().collect();
    match lines.as_slice() {
        [line] => format!("{indent}/** {line} */\n"),
        lines => {
            let body: String = lines
                .iter()
                .map(|line| match line.is_empty() {
                    true => format!("{indent} *\n"),
                    false => format!("{indent} * {line}\n"),
                })
                .collect();
            format!("{indent}/**\n{body}{indent} */\n")
        }
    }
}

fn record(out: &mut String, schema: &Schema, name: &str, fields: &[Field]) {
    writeln!(out, "export interface {name} {{").unwrap();
    for field in fields {
        out.push_str(&doc(&field.doc, "  "));
        writeln!(
            out,
            "  {}: {};",
            camel_case(&field.name),
            ts_type(schema, &field.r#type)
        )
        .unwrap();
    }
    out.push_str("}\n\n");
}

/// A named type: the type underneath, branded with the named type's full
/// name so that another named type over the same type doesn't fit it, and a
/// function of the same name that brands a value. The JSON is the value
/// underneath.
fn branded(out: &mut String, schema: &Schema, name: &str, full_name: &str, underlying: &Type) {
    let validation = if anyx_protocol::refinement::has_refinements(schema, underlying) {
        let index = schema
            .types
            .iter()
            .position(|definition| definition.name == full_name)
            .unwrap();
        format!("  encodeValue({{k:'named', index:{index}, args:[]}}, value);\n")
    } else {
        String::new()
    };
    let underlying = ts_type(schema, underlying);
    writeln!(
        out,
        "export type {name} = {underlying} & {{ readonly __brand: {full_name:?} }};\n"
    )
    .unwrap();
    writeln!(
        out,
        "/** Makes a `{name}` of a value, which the schema writes as its own. */\nexport function {name}(value: {underlying}): {name} {{\n{validation}  return value as {name};\n}}\n"
    )
    .unwrap();
}

/// A choice, or a method's errors: a union discriminated by `kind`.
fn union(out: &mut String, schema: &Schema, name: &str, variants: &[Shaped]) {
    writeln!(out, "export type {name} =").unwrap();
    for variant in variants {
        out.push_str(&doc(&variant.doc, "  "));
        let parameters: String = variant
            .shape
            .parameters
            .iter()
            .map(|parameter| {
                format!(
                    "; {}: {}",
                    camel_case(&parameter.name),
                    ts_type(schema, &parameter.r#type)
                )
            })
            .collect();
        writeln!(
            out,
            "  | {{ kind: {:?}{parameters} }}",
            camel_case(&variant.shape.words())
        )
        .unwrap();
    }
    out.truncate(out.trim_end().len());
    out.push_str(";\n\n");
}

// Compact, schema-specific descriptors consumed by the native runtime.
fn native_type(ty: &Type) -> String {
    match ty {
        Type::Refined(base, predicate) => format!(
            "{{k:'refined', item:{}, checks:{}}}",
            native_type(base),
            crate::refinement::checks(predicate)
        ),
        Type::Text => "{k:'text'}".into(),
        Type::Bytes => "{k:'bytes'}".into(),
        Type::Integer => "{k:'integer'}".into(),
        Type::Float => "{k:'float'}".into(),
        Type::Instant => "{k:'instant'}".into(),
        Type::Duration => "{k:'duration'}".into(),
        Type::List(item) => format!("{{k:'list', item:{}}}", native_type(item)),
        Type::Map(item) => format!("{{k:'map', item:{}}}", native_type(item)),
        Type::Named(index) => format!("{{k:'named', index:{index}, args:[]}}"),
        Type::Generic(index, args) => format!(
            "{{k:'named', index:{index}, args:[{}]}}",
            args.iter().map(native_type).collect::<Vec<_>>().join(",")
        ),
        Type::Parameter(name) => format!("{{k:'parameter', name:{name:?}}}"),
    }
}

fn native_shape(schema: &Schema, shape: &anyx_protocol::schema::Shape) -> String {
    format!(
        "{{text:{:?}, kind:{:?}, params:[{}]}}",
        shape.text,
        camel_case(&shape.words()),
        shape
            .parameters
            .iter()
            .map(|p| format!(
                "{{name:{:?}, type:{}, annotation:{:?}}}",
                camel_case(&p.name),
                native_type(&p.r#type),
                schema.type_name(&p.r#type)
            ))
            .collect::<Vec<_>>()
            .join(",")
    )
}

fn native_schema(schema: &Schema) -> String {
    let definitions = schema
        .types
        .iter()
        .map(|d| {
            let parameters = d
                .parameters
                .iter()
                .map(|p| format!("{p:?}"))
                .collect::<Vec<_>>()
                .join(",");
            let kind = match &d.kind {
                TypeKind::Distinct(t) => {
                    if anyx_protocol::refinement::has_refinements(schema, t) {
                        format!(
                            "kind:'distinct', name:{:?}, type:{}",
                            d.name,
                            native_type(t)
                        )
                    } else {
                        format!("kind:'distinct', type:{}", native_type(t))
                    }
                }
                TypeKind::Record(fields) => format!(
                    "kind:'record', fields:[{}]",
                    fields
                        .iter()
                        .map(|f| format!(
                            "{{wire:{:?}, name:{:?}, type:{}{}}}",
                            f.name,
                            camel_case(&f.name),
                            native_type(&f.r#type),
                            f.default.as_ref().map_or(String::new(), |v| format!(
                                ", defaultValue:()=>{}",
                                native_default(schema, &f.r#type, v)
                            ))
                        ))
                        .collect::<Vec<_>>()
                        .join(",")
                ),
                TypeKind::Choice(variants) => format!(
                    "kind:'choice', variants:[{}]",
                    variants
                        .iter()
                        .map(|v| native_shape(schema, &v.shape))
                        .collect::<Vec<_>>()
                        .join(",")
                ),
            };
            format!("{{parameters:[{parameters}],{kind}}}")
        })
        .collect::<Vec<_>>()
        .join(",\n");
    let methods = schema
        .methods
        .iter()
        .chain(&schema.built_ins)
        .map(|m| {
            format!(
                "[{:?}]:{{shape:{}, returns:{}, errors:[{}]}}",
                schema.call_name(m),
                native_shape(schema, &m.shape),
                m.returns
                    .as_ref()
                    .map_or("null".into(), |p| native_type(&p.r#type)),
                schema
                    .errors_of(m)
                    .iter()
                    .map(|e| native_shape(schema, &e.shape))
                    .collect::<Vec<_>>()
                    .join(",")
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    format!(
        "const definitions: Definition[] = [{definitions}];\nconst methods: Record<string, MethodDescriptor> = {{{methods}}};\n"
    )
}

fn native_default(schema: &Schema, ty: &Type, value: &anyx_protocol::value::Value) -> String {
    use anyx_protocol::value::Value;
    match value {
        Value::Text(s) => serde_json::to_string(s).expect("text default"),
        Value::Bytes(b) => format!("new Uint8Array({b:?})"),
        Value::Integer(n) => format!("{n}n"),
        Value::Float(n) => format!("{n:?}"),
        Value::Instant(t) => {
            let ms: i128 = match t.duration_since(std::time::UNIX_EPOCH) {
                Ok(d) => d.as_millis() as i128,
                Err(e) => -(e.duration().as_millis() as i128),
            };
            format!("new Date({ms})")
        }
        Value::Duration(d) => format!("{}n", d.as_millis()),
        Value::List(values) => {
            let Type::List(item) = schema.underlying(ty) else {
                unreachable!()
            };
            format!(
                "[{}]",
                values
                    .iter()
                    .map(|v| native_default(schema, item, v))
                    .collect::<Vec<_>>()
                    .join(",")
            )
        }
        Value::Map(values) => {
            let Type::Map(item) = schema.underlying(ty) else {
                unreachable!()
            };
            format!(
                "Object.fromEntries([{}])",
                values
                    .iter()
                    .map(|(k, v)| format!(
                        "[{},{}]",
                        serde_json::to_string(k).expect("map key"),
                        native_default(schema, item, v)
                    ))
                    .collect::<Vec<_>>()
                    .join(",")
            )
        }
        Value::Record(values) => {
            let (_, kind) = schema.instance(schema.underlying(ty)).expect("record");
            let TypeKind::Record(fields) = kind.as_ref() else {
                unreachable!()
            };
            format!(
                "{{{}}}",
                fields
                    .iter()
                    .filter_map(|f| values.get(&f.name).map(|v| format!(
                        "[{:?}]:{}",
                        camel_case(&f.name),
                        native_default(schema, &f.r#type, v)
                    )))
                    .collect::<Vec<_>>()
                    .join(",")
            )
        }
        Value::Variant { shape, arguments } => {
            let (_, kind) = schema.instance(schema.underlying(ty)).expect("choice");
            let TypeKind::Choice(variants) = kind.as_ref() else {
                unreachable!()
            };
            let variant = variants
                .iter()
                .find(|v| v.shape.text == *shape)
                .expect("variant");
            let fields = variant
                .shape
                .parameters
                .iter()
                .zip(arguments)
                .map(|(p, v)| {
                    format!(
                        ",[{:?}]:{}",
                        camel_case(&p.name),
                        native_default(schema, &p.r#type, v)
                    )
                })
                .collect::<String>();
            format!("{{kind:{:?}{fields}}}", camel_case(&variant.shape.words()))
        }
        Value::Nothing => "undefined".into(),
    }
}
